1	import { useState, useRef } from "react";
2	import { useParams, Link } from "react-router-dom";
3	import { useQuery } from "@tanstack/react-query";
4	import { supabase } from "@/integrations/supabase/client";
5	import { Button } from "@/components/ui/button";
6	import { Input } from "@/components/ui/input";
7	import { Label } from "@/components/ui/label";
8	import { Skeleton } from "@/components/ui/skeleton";
9	import { Textarea } from "@/components/ui/textarea";
10	import { Checkbox } from "@/components/ui/checkbox";
11	import {
12	  Select,
13	  SelectContent,
14	  SelectItem,
15	  SelectTrigger,
16	  SelectValue,
17	} from "@/components/ui/select";
18	import { toast } from "sonner";
19	import {
20	  CheckCircle2,
21	  Upload,
22	  FileText,
23	  X,
24	  Loader2,
25	  ExternalLink,
26	  Briefcase,
27	} from "lucide-react";
28	
29	const MAX_FILE_BYTES = 10 * 1024 * 1024; // 10 MB
30	const ALLOWED_EXTENSIONS = [".pdf", ".docx", ".doc", ".rtf", ".txt"];
31	const ALLOWED_MIME = [
32	  "application/pdf",
33	  "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
34	  "application/msword",
35	  "text/plain",
36	  "application/rtf",
37	  "text/rtf",
38	];
39	
40	function hasAllowedExtension(filename: string): boolean {
41	  const lower = filename.toLowerCase();
42	  return ALLOWED_EXTENSIONS.some((ext) => lower.endsWith(ext));
43	}
44	
45	interface JobInfo {
46	  id: string;
47	  title: string;
48	  status: string;
49	  job_description: string;
50	}
51	
52	type FormFieldType =
53	  | "text"
54	  | "number"
55	  | "select"
56	  | "multiselect"
57	  | "date"
58	  | "url"
59	  | "textarea"
60	  | "checkbox";
61	
62	interface JobFormField {
63	  id: string;
64	  field_type: FormFieldType;
65	  label: string;
66	  placeholder: string | null;
67	  required: boolean;
68	  options: string[] | null;
69	  sort_order: number;
70	}
71	
72	export default function Apply() {
73	  const { jobId } = useParams<{ jobId: string }>();
74	  const fileInputRef = useRef<HTMLInputElement>(null);
75	
76	  const [name, setName] = useState("");
77	  const [email, setEmail] = useState("");
78	  const [phone, setPhone] = useState("");
79	  const [linkedinUrl, setLinkedinUrl] = useState("");
80	  const [resumeFile, setResumeFile] = useState<File | null>(null);
81	  const [dragOver, setDragOver] = useState(false);
82	  const [submitting, setSubmitting] = useState(false);
83	  const [submitted, setSubmitted] = useState(false);
84	  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});
85	  // custom field values keyed by field id
86	  const [customValues, setCustomValues] = useState<Record<string, string | boolean | string[]>>({});
87	
88	  // Fetch minimal job info — no auth required via RPC
89	  const {
90	    data: job,
91	    isLoading: jobLoading,
92	    error: jobError,
93	  } = useQuery<JobInfo | null>({
94	    queryKey: ["apply-job-info", jobId],
95	    queryFn: async () => {
96	      if (!jobId) return null;
97	      const { data, error } = await supabase.rpc("get_job_apply_info", {
98	        p_job_id: jobId,
99	      });
100	      if (error) throw new Error(error.message);
101	      if (!data || (Array.isArray(data) && data.length === 0)) return null;
102	      const row = Array.isArray(data) ? data[0] : data;
103	      return row as JobInfo;
104	    },
105	    enabled: !!jobId,
106	    retry: 1,
107	    staleTime: 60_000,
108	  });
109	
110	  // Fetch custom form fields for this job (anon-accessible via RLS policy)
111	  const { data: formFields = [] } = useQuery<JobFormField[]>({
112	    queryKey: ["apply-form-fields", jobId],
113	    queryFn: async () => {
114	      if (!jobId) return [];
115	      const { data, error } = await (supabase as any)
116	        .rpc("get_job_form_fields", { p_job_id: jobId });
117	      if (error) return [];
118	      return (data ?? []) as JobFormField[];
119	    },
120	    enabled: !!jobId,
121	    staleTime: 60_000,
122	  });
123	
124	  const handleFileSelect = (file: File) => {
125	    if (file.size > MAX_FILE_BYTES) {
126	      toast.error("File exceeds 10MB limit");
127	      return;
128	    }
129	    if (!ALLOWED_MIME.includes(file.type) && !hasAllowedExtension(file.name)) {
130	      toast.error("Please upload a PDF, DOCX, DOC, RTF, or TXT file");
131	      return;
132	    }
133	    setResumeFile(file);
134	    setFieldErrors((prev) => ({ ...prev, resume: "" }));
135	  };
136	
137	  const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
138	    e.preventDefault();
139	    setDragOver(false);
140	    const file = e.dataTransfer.files[0];
141	    if (file) handleFileSelect(file);
142	  };
143	
144	  const validate = (): boolean => {
145	    const errors: Record<string, string> = {};
146	    if (!name.trim()) errors.name = "Name is required";
147	    if (!email.trim()) errors.email = "Email is required";
148	    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim()))
149	      errors.email = "Enter a valid email address";
150	
151	    // Validate required custom fields
152	    for (const field of formFields) {
153	      if (!field.required) continue;
154	      const val = customValues[field.id];
155	      if (
156	        val === undefined ||
157	        val === null ||
158	        val === "" ||
159	        (Array.isArray(val) && val.length === 0) ||
160	        (field.field_type === "checkbox" && val !== true)
161	      ) {
162	        errors[`custom_${field.id}`] = `${field.label} is required`;
163	      }
164	    }
165	
166	    setFieldErrors(errors);
167	    return Object.keys(errors).length === 0;
168	  };
169	
170	  const handleSubmit = async (e: React.FormEvent) => {
171	    e.preventDefault();
172	    if (!validate()) return;
173	    if (!jobId) {
174	      toast.error("Invalid application link");
175	      return;
176	    }
177	
178	    setSubmitting(true);
179	    try {
180	      const form = new FormData();
181	      form.append("job_id", jobId);
182	      form.append("name", name.trim());
183	      form.append("email", email.trim().toLowerCase());
184	      if (phone.trim()) form.append("phone", phone.trim());
185	      if (linkedinUrl.trim()) form.append("linkedin_url", linkedinUrl.trim());
186	      if (resumeFile) form.append("resume", resumeFile);
187	      // Append custom field values as JSON
188	      if (Object.keys(customValues).length > 0) {
189	        form.append("custom_fields", JSON.stringify(customValues));
190	      }
191	
192	      const { data: sessionData } = await supabase.auth.getSession();
193	      const headers: Record<string, string> = {
194	        // Supabase project URL and anon key from env — required even for anon calls
195	        apikey: import.meta.env.VITE_SUPABASE_ANON_KEY as string,
196	      };
197	      if (sessionData.session?.access_token) {
198	        headers["Authorization"] = `Bearer ${sessionData.session.access_token}`;
199	      } else {
200	        headers["Authorization"] = `Bearer ${import.meta.env.VITE_SUPABASE_ANON_KEY as string}`;
201	      }
202	
203	      const supabaseUrl = import.meta.env.VITE_SUPABASE_URL as string;
204	      const res = await fetch(
205	        `${supabaseUrl}/functions/v1/submit-application`,
206	        {
207	          method: "POST",
208	          headers,
209	          body: form,
210	        }
211	      );
212	
213	      const json = await res.json();
214	      if (!res.ok) {
215	        throw new Error(json.error || "Failed to submit application");
216	      }
217	
218	      setSubmitted(true);
219	    } catch (err: unknown) {
220	      const message =
221	        err instanceof Error ? err.message : "Submission failed. Please try again.";
222	      toast.error(message);
223	    } finally {
224	      setSubmitting(false);
225	    }
226	  };
227	
228	  // ── Success screen ──────────────────────────────────────────────────────
229	  if (submitted) {
230	    return (
231	      <div className="min-h-screen bg-background flex flex-col">
232	        <ApplyHeader />
233	        <main className="flex-1 flex items-center justify-center px-4 py-16">
234	          <div className="w-full max-w-md text-center space-y-6">
235	            <div className="flex justify-center">
236	              <div className="w-16 h-16 rounded-full bg-emerald-100 dark:bg-emerald-900/30 flex items-center justify-center">
237	                <CheckCircle2 className="h-8 w-8 text-emerald-600 dark:text-emerald-400" />
238	              </div>
239	            </div>
240	            <div className="space-y-2">
241	              <h1 className="text-2xl font-semibold tracking-tight">
242	                Application Submitted Successfully!
243	              </h1>
244	              <p className="text-sm text-muted-foreground leading-relaxed">
245	                Thank you! We will review your information and get in touch shortly.
246	              </p>
247	            </div>
248	            <Link
249	              to="/"
250	              className="inline-flex items-center gap-2 text-sm font-medium text-primary hover:text-primary/80 transition-colors"
251	            >
252	              Back to Jobs
253	            </Link>
254	          </div>
255	        </main>
256	        <ApplyFooter />
257	      </div>
258	    );
259	  }
260	
261	  // ── Job not found ───────────────────────────────────────────────────────
262	  // Note: status === "failed" means the ranking pipeline failed, NOT that the
263	  // job is closed for applications. We don't block applications on failed jobs.
264	  if (!jobLoading && (jobError || !job)) {
265	    return (
266	      <div className="min-h-screen bg-background flex flex-col">
267	        <ApplyHeader />
268	        <main className="flex-1 flex items-center justify-center px-4 py-16">
269	          <div className="w-full max-w-md text-center space-y-4">
270	            <div className="flex justify-center">
271	              <div className="w-14 h-14 rounded-full bg-muted flex items-center justify-center">
272	                <Briefcase className="h-7 w-7 text-muted-foreground" />
273	              </div>
274	            </div>
275	            <h1 className="text-xl font-semibold">Job not found</h1>
276	            <p className="text-sm text-muted-foreground">
277	              This application link may have expired or the job no longer exists.
278	            </p>
279	            <Link
280	              to="/"
281	              className="inline-flex items-center gap-2 text-sm font-medium text-primary hover:text-primary/80 transition-colors"
282	            >
283	              Back to Jobs
284	            </Link>
285	          </div>
286	        </main>
287	        <ApplyFooter />
288	      </div>
289	    );
290	  }
291	
292	  return (
293	    <div className="min-h-screen bg-background flex flex-col">
294	      <ApplyHeader />
295	
296	      <main className="flex-1 flex items-start justify-center px-4 py-10">
297	        <div className="w-full max-w-lg">
298	          {/* Job title */}
299	          <div className="mb-8 space-y-1">
300	            {jobLoading ? (
301	              <>
302	                <Skeleton className="h-7 w-64" />
303	                <Skeleton className="h-4 w-40 mt-2" />
304	              </>
305	            ) : (
306	              <>
307	                <h1 className="text-2xl font-semibold tracking-tight leading-tight">
308	                  {job?.title ?? "Apply for this position"}
309	                </h1>
310	                {job?.job_description && (
311	                  <div className="mt-4 rounded-lg border border-border bg-muted/30 p-4 max-h-60 overflow-y-auto">
312	                    <h2 className="text-xs font-semibold text-muted-foreground uppercase tracking-wide mb-2">
313	                      Job Description
314	                    </h2>
315	                    <p className="text-sm text-foreground whitespace-pre-line leading-relaxed">
316	                      {job.job_description}
317	                    </p>
318	                  </div>
319	                )}
320	                <p className="text-sm text-muted-foreground mt-3">
321	                  Fill in your details below to apply.
322	                </p>
323	              </>
324	            )}
325	          </div>
326	
327	          <form onSubmit={handleSubmit} noValidate className="space-y-5">
328	            {/* Name */}
329	            <div className="space-y-1.5">
330	              <Label htmlFor="apply-name">
331	                Full Name <span className="text-destructive">*</span>
332	              </Label>
333	              <Input
334	                id="apply-name"
335	                type="text"
336	                placeholder="Jane Smith"
337	                value={name}
338	                onChange={(e) => {
339	                  setName(e.target.value);
340	                  if (fieldErrors.name)
341	                    setFieldErrors((prev) => ({ ...prev, name: "" }));
342	                }}
343	                autoComplete="name"
344	                aria-invalid={!!fieldErrors.name}
345	                aria-describedby={fieldErrors.name ? "name-error" : undefined}
346	                disabled={submitting}
347	              />
348	              {fieldErrors.name && (
349	                <p id="name-error" className="text-xs text-destructive">
350	                  {fieldErrors.name}
351	                </p>
352	              )}
353	            </div>
354	
355	            {/* Email */}
356	            <div className="space-y-1.5">
357	              <Label htmlFor="apply-email">
358	                Email Address <span className="text-destructive">*</span>
359	              </Label>
360	              <Input
361	                id="apply-email"
362	                type="email"
363	                placeholder="jane@example.com"
364	                value={email}
365	                onChange={(e) => {
366	                  setEmail(e.target.value);
367	                  if (fieldErrors.email)
368	                    setFieldErrors((prev) => ({ ...prev, email: "" }));
369	                }}
370	                autoComplete="email"
371	                aria-invalid={!!fieldErrors.email}
372	                aria-describedby={fieldErrors.email ? "email-error" : undefined}
373	                disabled={submitting}
374	              />
375	              {fieldErrors.email && (
376	                <p id="email-error" className="text-xs text-destructive">
377	                  {fieldErrors.email}
378	                </p>
379	              )}
380	            </div>
381	
382	            {/* Phone */}
383	            <div className="space-y-1.5">
384	              <Label htmlFor="apply-phone">Phone Number</Label>
385	              <Input
386	                id="apply-phone"
387	                type="tel"
388	                placeholder="+1 555 000 0000"
389	                value={phone}
390	                onChange={(e) => setPhone(e.target.value)}
391	                autoComplete="tel"
392	                disabled={submitting}
393	              />
394	            </div>
395	
396	            {/* Resume Upload */}
397	            <div className="space-y-1.5">
398	              <Label>Resume / CV <span className="text-xs font-normal text-muted-foreground">(optional)</span></Label>
399	              {resumeFile ? (
400	                <div className="flex items-center gap-3 rounded-lg border border-border bg-secondary/40 px-4 py-3">
401	                  <FileText className="h-5 w-5 text-primary shrink-0" />
402	                  <span className="flex-1 text-sm truncate">{resumeFile.name}</span>
403	                  <button
404	                    type="button"
405	                    onClick={() => {
406	                      setResumeFile(null);
407	                      if (fileInputRef.current) fileInputRef.current.value = "";
408	                    }}
409	                    className="text-muted-foreground hover:text-destructive transition-colors"
410	                    aria-label="Remove resume"
411	                    disabled={submitting}
412	                  >
413	                    <X className="h-4 w-4" />
414	                  </button>
415	                </div>
416	              ) : (
417	                <div
418	                  role="button"
419	                  tabIndex={0}
420	                  aria-label="Upload resume — PDF, DOCX, DOC, RTF, or TXT, max 10MB"
421	                  onKeyDown={(e) => {
422	                    if (e.key === "Enter" || e.key === " ")
423	                      fileInputRef.current?.click();
424	                  }}
425	                  className={`border-2 border-dashed rounded-lg p-6 text-center cursor-pointer transition-all duration-200 flex flex-col items-center gap-2 focus:outline-none focus-visible:ring-2 focus-visible:ring-ring ${
426	                    dragOver
427	                      ? "border-primary bg-primary/5 scale-[1.01]"
428	                      : "border-border hover:border-primary/50 hover:bg-primary/[0.02]"
429	                  }`}
430	                  onDragOver={(e) => {
431	                    e.preventDefault();
432	                    setDragOver(true);
433	                  }}
434	                  onDragLeave={() => setDragOver(false)}
435	                  onDrop={handleDrop}
436	                  onClick={() => fileInputRef.current?.click()}
437	                >
438	                  <div className="w-10 h-10 rounded-lg bg-muted flex items-center justify-center">
439	                    <Upload className="h-5 w-5 text-primary" />
440	                  </div>
441	                  <p className="text-sm font-medium text-foreground">
442	                    Drop your resume here or{" "}
443	                    <span className="text-primary">click to browse</span>
444	                  </p>
445	                  <p className="text-xs text-muted-foreground">
446	                    PDF, DOCX, DOC, RTF, TXT · Max 10MB
447	                  </p>
448	                  <input
449	                    ref={fileInputRef}
450	                    id="resume-input"
451	                    type="file"
452	                    className="hidden"
453	                    accept=".pdf,.docx,.doc,.rtf,.txt"
454	                    onChange={(e) => {
455	                      const file = e.target.files?.[0];
456	                      if (file) handleFileSelect(file);
457	                    }}
458	                    disabled={submitting}
459	                  />
460	                </div>
461	              )}
462	            </div>
463	
464	            {/* LinkedIn URL */}
465	            <div className="space-y-1.5">
466	              <Label htmlFor="apply-linkedin" className="flex items-center gap-1.5">
467	                LinkedIn Profile
468	                <span className="text-xs font-normal text-muted-foreground">
469	                  (optional)
470	                </span>
471	              </Label>
472	              <div className="relative">
473	                <Input
474	                  id="apply-linkedin"
475	                  type="url"
476	                  placeholder="https://linkedin.com/in/jane-smith"
477	                  value={linkedinUrl}
478	                  onChange={(e) => setLinkedinUrl(e.target.value)}
479	                  className="pr-9"
480	                  disabled={submitting}
481	                />
482	                <ExternalLink className="absolute right-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground pointer-events-none" />
483	              </div>
484	            </div>
485	
486	            {/* Custom fields */}
487	            {formFields.length > 0 && (
488	              <div className="space-y-5 border-t border-border pt-5">
489	                <p className="text-xs font-medium text-muted-foreground uppercase tracking-wider">
490	                  Additional Questions
491	                </p>
492	                {formFields.map((field) => (
493	                  <CustomFieldInput
494	                    key={field.id}
495	                    field={field}
496	                    value={customValues[field.id]}
497	                    onChange={(val) =>
498	                      setCustomValues((prev) => ({ ...prev, [field.id]: val }))
499	                    }
500	                    error={fieldErrors[`custom_${field.id}`]}
501	                    disabled={submitting}
502	                  />
503	                ))}
504	              </div>
505	            )}
506	
507	            {/* Privacy notice */}
508	            <p className="text-[11px] text-muted-foreground/60 leading-relaxed">
509	              By submitting this application, you consent to your information being processed for recruitment purposes by the hiring company.
510	            </p>
511	
512	            {/* Submit */}
513	            <Button
514	              type="submit"
515	              className="w-full gap-2"
516	              size="lg"
517	              disabled={submitting}
518	            >
519	              {submitting ? (
520	                <>
521	                  <Loader2 className="h-4 w-4 animate-spin" />
522	                  Submitting…
523	                </>
524	              ) : (
525	                "Submit Application"
526	              )}
527	            </Button>
528	          </form>
529	        </div>
530	      </main>
531	
532	      <ApplyFooter />
533	    </div>
534	  );
535	}
536	
537	// ── Custom Field Input renderer ─────────────────────────────────────────────
538	
539	interface CustomFieldInputProps {
540	  field: JobFormField;
541	  value: string | boolean | string[] | undefined;
542	  onChange: (val: string | boolean | string[]) => void;
543	  error?: string;
544	  disabled: boolean;
545	}
546	
547	function CustomFieldInput({
548	  field,
549	  value,
550	  onChange,
551	  error,
552	  disabled,
553	}: CustomFieldInputProps) {
554	  const fieldId = `custom-${field.id}`;
555	  const strVal = typeof value === "string" ? value : "";
556	  const boolVal = typeof value === "boolean" ? value : false;
557	  const arrVal = Array.isArray(value) ? value : [];
558	
559	  return (
560	    <div className="space-y-1.5">
561	      <Label htmlFor={fieldId}>
562	        {field.label}
563	        {field.required && <span className="text-destructive ml-1">*</span>}
564	      </Label>
565	
566	      {field.field_type === "text" && (
567	        <Input
568	          id={fieldId}
569	          type="text"
570	          placeholder={field.placeholder ?? ""}
571	          value={strVal}
572	          onChange={(e) => onChange(e.target.value)}
573	          aria-invalid={!!error}
574	          disabled={disabled}
575	        />
576	      )}
577	
578	      {field.field_type === "number" && (
579	        <Input
580	          id={fieldId}
581	          type="number"
582	          placeholder={field.placeholder ?? ""}
583	          value={strVal}
584	          onChange={(e) => onChange(e.target.value)}
585	          aria-invalid={!!error}
586	          disabled={disabled}
587	        />
588	      )}
589	
590	      {field.field_type === "url" && (
591	        <Input
592	          id={fieldId}
593	          type="url"
594	          placeholder={field.placeholder ?? "https://"}
595	          value={strVal}
596	          onChange={(e) => onChange(e.target.value)}
597	          aria-invalid={!!error}
598	          disabled={disabled}
599	        />
600	      )}
601	
602	      {field.field_type === "date" && (
603	        <Input
604	          id={fieldId}
605	          type="date"
606	          value={strVal}
607	          onChange={(e) => onChange(e.target.value)}
608	          aria-invalid={!!error}
609	          disabled={disabled}
610	        />
611	      )}
612	
613	      {field.field_type === "textarea" && (
614	        <Textarea
615	          id={fieldId}
616	          placeholder={field.placeholder ?? ""}
617	          value={strVal}
618	          onChange={(e) => onChange(e.target.value)}
619	          aria-invalid={!!error}
620	          disabled={disabled}
621	          rows={4}
622	          className="resize-none"
623	        />
624	      )}
625	
626	      {field.field_type === "checkbox" && (
627	        <div className="flex items-center gap-2">
628	          <Checkbox
629	            id={fieldId}
630	            checked={boolVal}
631	            onCheckedChange={(checked) => onChange(!!checked)}
632	            aria-invalid={!!error}
633	            disabled={disabled}
634	          />
635	          <Label htmlFor={fieldId} className="text-sm font-normal cursor-pointer">
636	            {field.placeholder ?? "Yes"}
637	          </Label>
638	        </div>
639	      )}
640	
641	      {field.field_type === "select" && (
642	        <Select
643	          value={strVal}
644	          onValueChange={onChange}
645	          disabled={disabled}
646	        >
647	          <SelectTrigger id={fieldId} aria-invalid={!!error}>
